    if (pWorkSpace == nullptr) { return; }
    // GrowBControl candidate 8 of 33
    // Exploration cases: 0
    // Structural maximin 294 / 336; family total 2070
    std::uint8_t *aSourceLaneA = pWorkSpace->mShadowLaneA;
    std::uint8_t *aSourceLaneB = pWorkSpace->mShadowLaneB;
